import{_ as d,o as a,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"消费者保护法","description":"","frontmatter":{},"headers":[],"relativePath":"zh/0042-消费者保护法.md","filePath":"zh/0042-消费者保护法.md"}'),e={name:"zh/0042-消费者保护法.md"};function i(o,t,h,n,s,b){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="消费者保护法" tabindex="-1">消费者保护法 <a class="header-anchor" href="#消费者保护法" aria-label="Permalink to &quot;消费者保护法&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>42</td></tr><tr><td>所属模块</td><td>法律体系与治理框架</td></tr><tr><td>核心关键词</td><td>消费者权利、公平交易、反欺诈、产品责任、共生市场</td></tr></tbody></table><h2 id="一、立法目的与适用范围" tabindex="-1">一、立法目的与适用范围 <a class="header-anchor" href="#一、立法目的与适用范围" aria-label="Permalink to &quot;一、立法目的与适用范围&quot;">​</a></h2><p>《消费者保护法》是锚点共生文明法律体系中的核心法律之一，与《共生劳动法》共同构成经济生活的两大支柱。本法旨在保护衡元宙内一切消费者的合法权益，规范市场交易行为，维护公平、诚信、共生的市场秩序，防止掠夺式商业行为对众生权益的侵害。</p><p>本法适用于衡元宙内一切为满足个人或家庭生活需要而购买、使用商品或接受服务的消费者，以及为消费者提供商品或服务的经营者。跨位面交易同样适用本法，但可根据位面差异制定实施细则。</p><h2 id="二、消费者基本权利" tabindex="-1">二、消费者基本权利 <a class="header-anchor" href="#二、消费者基本权利" aria-label="Permalink to &quot;二、消费者基本权利&quot;">​</a></h2><p>本法确立消费者享有以下九项基本权利：</p><table tabindex="0"><thead><tr><th>权利</th><th>内涵</th></tr></thead><tbody><tr><td>安全保障权</td><td>消费者在购买、使用商品和接受服务时享有人身、财产安全不受损害的权利</td></tr><tr><td>知悉真情权</td><td>消费者有权知悉其购买、使用的商品或接受的服务的真实情况，包括成分、功效、风险等</td></tr><tr><td>自主选择权</td><td>消费者有权自主选择商品或服务，有权进行比较、鉴别和挑选，拒绝强制交易</td></tr><tr><td>公平交易权</td><td>消费者有权获得质量保障、价格合理、计量正确等公平交易条件</td></tr><tr><td>依法求偿权</td><td>消费者因购买、使用商品或接受服务受到人身、财产损害的，享有依法获得赔偿的权利</td></tr><tr><td>结社维权权</td><td>消费者有权依法成立或加入消费者组织，维护自身合法权益</td></tr><tr><td>获得知识权</td><td>消费者有权获得有关消费和消费者权益保护方面的知识与信息</td></tr><tr><td>受尊重权</td><td>消费者在购买、使用商品和接受服务时，享有人格尊严、民族风俗习惯得到尊重的权利</td></tr><tr><td>监督权</td><td>消费者有权对商品和服务以及消费者权益保护工作进行监督，提出批评与建议</td></tr></tbody></table><h2 id="三、经营者义务" tabindex="-1">三、经营者义务 <a class="header-anchor" href="#三、经营者义务" aria-label="Permalink to &quot;三、经营者义务&quot;">​</a></h2><p>经营者在向消费者提供商品或服务时，应当履行以下义务：</p><ol><li><strong>依法经营义务</strong>：经营者必须遵守宪法与法律，在核准的经营范围内从事经营活动。</li><li><strong>安全保障义务</strong>：经营者应当保证其提供的商品或服务符合保障人身、财产安全的要求，对可能危及安全的商品和服务应当作出真实说明和明确警示。</li><li><strong>真实信息义务</strong>：经营者应当向消费者提供有关商品或服务的真实信息，不得作虚假或引人误解的宣传。修炼类商品与服务必须如实标注功效边界与潜在风险。</li><li><strong>质量保证义务</strong>：经营者应当保证在正常使用商品或接受服务的情况下，其提供的商品或服务应当具有的质量、性能、用途和有效期限。</li><li><strong>公平交易义务</strong>：经营者不得以格式条款、通知、声明、店堂告示等方式作出排除或限制消费者权利、减轻或免除经营者责任、加重消费者责任等对消费者不公平、不合理的规定。</li><li><strong>售后服务义务</strong>：经营者应当按照国家规定或与消费者的约定，承担修理、更换、退货及其他售后服务责任。</li><li><strong>保护隐私义务</strong>：经营者应当保护消费者的个人信息与意识数据，未经消费者同意不得收集、使用或泄露。</li></ol><h2 id="四、争议解决与法律责任" tabindex="-1">四、争议解决与法律责任 <a class="header-anchor" href="#四、争议解决与法律责任" aria-label="Permalink to &quot;四、争议解决与法律责任&quot;">​</a></h2><p>消费者与经营者发生消费者权益争议的，可以通过以下途径解决：</p><ul><li>与经营者协商和解</li><li>请求消费者组织调解</li><li>向有关行政部门投诉</li><li>根据与经营者达成的仲裁协议提请仲裁机构仲裁</li><li>向共生法院提起诉讼</li></ul><p>经营者违反本法规定，侵害消费者合法权益的，应当承担以下责任：</p><table tabindex="0"><thead><tr><th>违法行为</th><th>法律责任</th></tr></thead><tbody><tr><td>提供缺陷商品或服务造成损害</td><td>承担赔偿责任，包括医疗费、误工费、残疾赔偿金等</td></tr><tr><td>欺诈行为</td><td>按照消费者要求增加赔偿，金额为消费者购买商品价款或接受服务费用的三倍</td></tr><tr><td>虚假宣传</td><td>责令停止违法行为，消除影响，处以罚款</td></tr><tr><td>强制交易</td><td>责令改正，退还不合理费用，处以罚款</td></tr><tr><td>侵犯消费者隐私</td><td>承担精神损害赔偿，情节严重的追究刑事责任</td></tr></tbody></table><h2 id="五、消费者组织与社会监督" tabindex="-1">五、消费者组织与社会监督 <a class="header-anchor" href="#五、消费者组织与社会监督" aria-label="Permalink to &quot;五、消费者组织与社会监督&quot;">​</a></h2><p>国家鼓励、支持一切组织和个人对损害消费者合法权益的行为进行社会监督。消费者协会是依法成立的对商品和服务进行社会监督的保护消费者合法权益的社会组织，履行以下职能：</p><ol><li>向消费者提供消费信息和咨询服务</li><li>参与有关行政部门对商品和服务的监督、检查</li><li>就有关消费者合法权益的问题，向有关行政部门反映、查询，提出建议</li><li>受理消费者的投诉，并对投诉事项进行调查、调解</li><li>对损害消费者合法权益的行为，支持受损害的消费者提起诉讼</li></ol><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>《消费者保护法》是锚点共生文明市场秩序的守护者。它通过赋予消费者充分权利、约束经营者行为、建立多元争议解决机制，确保市场交易在公平、诚信、共生的轨道上运行，防止商业领域成为掠夺式行为的新温床。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>0040-共生宪法总纲</li><li>0041-共生劳动法</li><li>0047-反垄断法</li><li>0036-社会结构与阶层流动</li></ul>',23)])])}const p=d(e,[["render",i]]);export{_ as __pageData,p as default};
